// 真实travel候选的有限安全门；比较原手动submit和许可提交的完整checkpoint字节。
#include "hanmo/resident_world_api.hpp"
#include "resident/kernel/world_codec.hpp"
#include "resident/kernel/command_types.hpp"
#include "resident/kernel/continuation_snapshot.hpp"
#include <fstream>
#include <iostream>
#include <sstream>
using namespace hanmo::resident;
namespace {
int checks=0;
// 失败立即终止以免使用无效夹具掩盖后续错误。
void check(bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);}
BoundaryValue read(const std::string& path){std::ifstream file(path);std::ostringstream text;text<<file.rdbuf();auto parsed=parse_boundary_json(text.str());if(!parsed.ok)throw std::runtime_error(parsed.error.original.code+":"+path);return std::move(parsed.value);}
template<class T> T take(Outcome<T> result){if(!result.ok)throw std::runtime_error(result.error.original.code);return std::move(result.value);}
// 手动对照仍使用同一个正式advance和请求序号，没有测试专用世界推进。
CommandEnvelope advance(const ResidentWorld& world,Integer sequence){auto id=take(world.identity());return {id.world_id,id.execution_epoch,sequence,id.revision,"actor.player",std::make_shared<const CommandPayload>(CommandPayload{"advance",AdvanceCommand{}})};}
RunRef reference(const ResidentWorld& world,const StableId& id){auto identity=take(world.identity());return {identity.world_id,identity.execution_epoch,id};}
}
int main(int argc,char** argv){if(argc!=2)return 2;try{
    const std::string root=argv[1];auto index=read(root+"/oracle-index.json");auto catalog=read(root+"/expanded-catalog.json");auto source=read(root+"/"+*index.find("initial_state")->find("file")->as<StableId>());auto prepared=take(prepare_catalog(catalog,source));auto seed=take(decode_world_seed(source,*prepared));ResidentWorld initial;check(initial.install(prepared,std::move(seed)).ok,"real seed installs");
    auto travel=take(decode_resident_command("travel",*index.find("commands")->as<BoundaryValue::Array>()->front().find("command")->find("params")));auto identity=take(initial.identity());auto started=take(initial.submit({identity.world_id,identity.execution_epoch,1,identity.revision,"actor.player",std::make_shared<const CommandPayload>(travel)}));const auto action=std::get<ActionStarted>(started->details->data).action_id;const auto base=take(initial.checkpoint());
    ResidentWorld run,manual;check(run.restore(base,prepared).ok&&manual.restore(base,prepared).ok,"same accepted travel clones");auto beginning=take(run.identity());auto parked=take(run.begin_run({beginning,"run:one","actor.player",action,1,100000}));check(parked.committed_half_days==0&&take(run.checkpoint())==base,"begin parks without effects");
    auto first=take(run.resume_run({beginning,"run:one",1,1}));check(first.committed_half_days==1&&first.remaining_half_days==0&&first.stop==RunStop::budget_exhausted,"one successful halfday exhausts time");check(first.gross_outflow>0&&first.gross_outflow<=100000,"actual travel spending observed");take(manual.submit(advance(manual,2)));auto after=take(run.checkpoint());check(after==take(manual.checkpoint()),"bounded step exactly equals original manual world");auto duplicate=take(run.resume_run({beginning,"run:one",1,1}));check(duplicate.committed_half_days==1&&take(run.checkpoint())==after,"old-revision duplicate permit is idempotent");
    auto exhausted=take(run.resume_run({take(run.identity()),"run:one",2,3}));check(exhausted.committed_half_days==1&&take(run.checkpoint())==after,"terminal multistep permit does nothing");
    ResidentWorld cheap;check(cheap.restore(base,prepared).ok,"budget refusal setup");auto cheap_id=take(cheap.identity());take(cheap.begin_run({cheap_id,"run:cheap","actor.player",action,4,first.gross_outflow-1}));auto denied=take(cheap.resume_run({cheap_id,"run:cheap",1,1}));check(denied.stop==RunStop::money_budget_exhausted&&denied.committed_half_days==0&&denied.gross_outflow==0,"candidate overspend stops with zero progress");check(take(cheap.checkpoint())==base,"over-budget candidate has zero committed world effects");take(cheap.submit(advance(cheap,2)));check(take(cheap.checkpoint())==after,"refusal preserves next request and clears spend guard for manual submit");
    ResidentWorld paused;check(paused.restore(base,prepared).ok,"remaining-context setup");auto paused_id=take(paused.identity());take(paused.begin_run({paused_id,"run:old","actor.player",action,4,100000}));auto progressed=take(paused.resume_run({paused_id,"run:old",1,1}));auto current=take(paused.identity());const auto before_cancel=take(paused.checkpoint());take(paused.cancel_run(reference(paused,"run:old")));check(take(paused.checkpoint())==before_cancel,"driver stop never pauses or cancels action");auto snapshot=take(paused.continuation_snapshot());check(snapshot.has_value()&&snapshot->max_half_days==4&&snapshot->committed_half_days==1&&snapshot->gross_outflow==progressed.gross_outflow,"stopped context preserves frozen totals");
    auto resumed=take(paused.begin_run({current,"run:remaining","actor.player",action,3,100000-progressed.gross_outflow,true}));check(resumed.max_half_days==4&&resumed.committed_half_days==1&&resumed.gross_outflow==progressed.gross_outflow,"explicit remaining continuation preserves original accounting");take(paused.cancel_run(reference(paused,"run:remaining")));auto saved_context=take(paused.continuation_snapshot());check(saved_context.has_value(),"stopped renewed scope saves");
    // 原世界与在途许可必须在三参数冷恢复失败时一起保留，不能先换世界再核许可。
    ResidentWorld atomic;check(atomic.restore(base,prepared).ok,"atomic restore previous world setup");const auto prior_identity=take(atomic.identity());take(atomic.begin_run({prior_identity,"run:prior","actor.player",action,4,100000}));const auto prior_bytes=take(atomic.checkpoint());
    auto refused_pair=[&](const ContinuationSnapshot& invalid,const char* label){
        check(!atomic.restore(before_cancel,prepared,invalid).ok,label);const auto still=take(atomic.identity());
        check(still.world_id==prior_identity.world_id&&still.execution_epoch==prior_identity.execution_epoch&&still.revision==prior_identity.revision&&still.tick==prior_identity.tick&&take(atomic.checkpoint())==prior_bytes,"failed atomic restore retains prior world bytes and exact epoch");
        auto prior_run=take(atomic.poll_run({prior_identity.world_id,prior_identity.execution_epoch,"run:prior"}));check(prior_run.stop==RunStop::awaiting_permit&&prior_run.committed_half_days==0,"failed atomic restore retains prior parked run");
    };
    auto invalid_pair=*saved_context;invalid_pair.source_identity.world_id[0]^=1;refused_pair(invalid_pair,"atomic restore refuses foreign source world");invalid_pair=*saved_context;invalid_pair.action_id="action:other";refused_pair(invalid_pair,"atomic restore refuses replacement action");invalid_pair=*saved_context;invalid_pair.wallet_id="wallet:other";refused_pair(invalid_pair,"atomic restore refuses foreign personal wallet");
    check(atomic.restore(before_cancel,prepared,saved_context).ok,"matching world and continuation restore atomically");const auto atomic_identity=take(atomic.identity());check(atomic_identity.world_id==saved_context->source_identity.world_id&&atomic_identity.tick==saved_context->source_identity.tick&&atomic_identity.revision==saved_context->source_identity.revision&&atomic_identity.execution_epoch!=prior_identity.execution_epoch&&atomic_identity.execution_epoch!=saved_context->source_identity.execution_epoch&&take(atomic.checkpoint())==before_cancel,"successful atomic restore adopts saved world in fresh epoch");
    auto atomic_context=take(atomic.continuation_snapshot());check(atomic_context&&atomic_context->stop==RunStop::restored&&atomic_context->source_identity.execution_epoch==atomic_identity.execution_epoch&&atomic_context->max_half_days==saved_context->max_half_days&&atomic_context->max_gross_outflow==saved_context->max_gross_outflow&&atomic_context->committed_half_days==saved_context->committed_half_days&&atomic_context->gross_outflow==saved_context->gross_outflow&&atomic_context->started_tick==saved_context->started_tick,"atomic restore preserves original totals as stopped current-epoch context");
    auto stale_prior=atomic.poll_run({prior_identity.world_id,prior_identity.execution_epoch,"run:prior"});check(!stale_prior.ok&&stale_prior.error.original.code=="StaleWorld","atomic restore invalidates previous epoch callback");auto absent_run=atomic.poll_run({atomic_identity.world_id,atomic_identity.execution_epoch,"run:prior"});check(!absent_run.ok&&absent_run.error.original.code=="UnknownRun","successful atomic restore creates no active run");auto absent_permit=atomic.resume_run({atomic_identity,"run:remaining",1,1});check(!absent_permit.ok&&absent_permit.error.original.code=="UnknownRun"&&take(atomic.checkpoint())==before_cancel,"restored scope alone cannot spend a permit");
    ResidentWorld restored;check(restored.restore(before_cancel,prepared).ok,"cold world restores");const auto stable=take(restored.checkpoint());auto corrupt=*saved_context;corrupt.source_identity.world_id[0]^=1;check(!restored.restore_continuation(corrupt).ok&&take(restored.checkpoint())==stable,"wrong world context refused without effects");corrupt=*saved_context;corrupt.wallet_id="wallet:other";check(!restored.restore_continuation(corrupt).ok,"foreign wallet context refused");corrupt=*saved_context;corrupt.action_id="action:other";check(!restored.restore_continuation(corrupt).ok,"replacement action context refused");check(restored.restore_continuation(*saved_context).ok,"native validates actual original action");auto stopped=take(restored.continuation_snapshot());check(stopped&&stopped->stop==RunStop::restored&&take(restored.checkpoint())==stable,"cold restore only returns stopped context");check(!restored.poll_run({current.world_id,current.execution_epoch,"run:remaining"}).ok,"old epoch cannot poll restored execution");auto restored_identity=take(restored.identity());check(!restored.resume_run({restored_identity,"run:remaining",1,1}).ok,"snapshot carries no reusable run ID");auto new_run=take(restored.begin_run({restored_identity,"run:new","actor.player",action,3,100000-progressed.gross_outflow,true}));check(new_run.committed_half_days==1&&new_run.permit_seq==0,"confirmation creates fresh permit sequence with original usage");take(restored.cancel_run(reference(restored,"run:new")));take(restored.submit(advance(restored,3)));check(!take(restored.continuation_snapshot()).has_value(),"intervening manual gameplay invalidates remaining context");check(!restored.begin_run({take(restored.identity()),"run:stale-scope","actor.player",action,3,100000-progressed.gross_outflow,true}).ok,"stale remaining approval cannot authorize new steps");
    std::cout<<"KERNEL_BOUNDED_RUN "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& error){std::cerr<<"KERNEL_BOUNDED_RUN_FAILURE "<<error.what()<<" after "<<checks<<" checks\n";return 1;}}
